mapper.select:
SELECT COUNT(*)
FROM project_members
WHERE project_id = #{projectId}
  AND employee_id = #{employeeId}
  AND status = 'ACTIVE'

mapper.update:
UPDATE project_members
SET status = 'INACTIVE',
    left_at = NOW()
WHERE project_id = #{projectId}
  AND employee_id = #{employeeId}
  AND status = 'ACTIVE'
